def compile_mjcf(facts,out):
 bp=[('bench_base',''),('rear_pedestal','bench_base'),('rear_bearing','rear_pedestal'),('front_pedestal','bench_base'),('front_bearing','front_pedestal'),('left_guide_rail','bench_base'),('right_guide_rail','bench_base'),('cylinder_lower_frame','left_guide_rail'),('cylinder_left_post','cylinder_lower_frame'),('cylinder_right_post','cylinder_lower_frame'),('cylinder_upper_frame','cylinder_left_post'),('crankshaft','bench_base'),('crank_web','crankshaft'),('crank_pin','crank_web'),('crosshead','bench_base'),('wrist_pin','crosshead'),('connecting_rod','wrist_pin'),('pump_rod','crosshead'),('pump_piston','pump_rod'),('hand_crank_arm','crankshaft'),('handle_pin','hand_crank_arm'),('hand_grip','handle_pin')]
