 P=[('crankshaft','rear_bearing'),('crankshaft','front_bearing'),('crankshaft','crank_web'),('connecting_rod','crankshaft'),('crankshaft','hand_crank_arm'),('crankshaft','rear_pedestal'),('crankshaft','front_pedestal'),('crank_pin','crankshaft'),('crankshaft','left_guide_rail'),('crankshaft','right_guide_rail'),('crankshaft','hand_grip'),('crankshaft','handle_pin'),('crankshaft','crosshead'),('crankshaft','wrist_pin'),('bench_base','crankshaft'),('crankshaft','pump_rod'),('crank_pin','crank_web'),('crank_web','front_bearing'),('connecting_rod','crank_web'),('crank_web','front_pedestal'),('crank_web','right_guide_rail'),('crank_web','left_guide_rail'),('connecting_rod','crank_pin'),('crank_pin','right_guide_rail'),('crank_pin','front_bearing'),('crank_pin','front_pedestal'),('connecting_rod','crosshead'),('connecting_rod','wrist_pin'),('connecting_rod','pump_rod'),('connecting_rod','front_pedestal'),('connecting_rod','right_guide_rail'),('connecting_rod','left_guide_rail'),('connecting_rod','front_bearing'),('connecting_rod','cylinder_lower_frame'),('connecting_rod','cylinder_right_post'),('connecting_rod','cylinder_left_post'),('bench_base','connecting_rod'),('crosshead','wrist_pin'),('crosshead','pump_rod'),('crosshead','left_guide_rail'),('crosshead','right_guide_rail'),('crosshead','cylinder_lower_frame'),('pump_rod','wrist_pin'),('left_guide_rail','wrist_pin'),('right_guide_rail','wrist_pin'),('pump_piston','pump_rod'),('cylinder_lower_frame','pump_rod'),('cylinder_left_post','pump_rod'),('cylinder_right_post','pump_rod'),('left_guide_rail','pump_rod'),('pump_rod','right_guide_rail'),('cylinder_left_post','pump_piston'),('cylinder_right_post','pump_piston'),('cylinder_lower_frame','pump_piston'),('hand_crank_arm','handle_pin'),('hand_crank_arm','hand_grip'),('hand_crank_arm','rear_pedestal'),('hand_crank_arm','rear_bearing'),('hand_grip','handle_pin')]
 R={('crankshaft','rear_bearing'):'relation/rear_shaft_journal',('crankshaft','front_bearing'):'relation/front_shaft_journal',('crankshaft','crank_web'):'relation/shaft_to_crank_web',('crank_pin','crank_web'):'relation/web_to_eccentric_pin',('connecting_rod','crank_pin'):'relation/crank_pin_big_end',('crosshead','wrist_pin'):'relation/crosshead_to_wrist_pin',('connecting_rod','wrist_pin'):'relation/wrist_pin_small_end',('crosshead','pump_rod'):'relation/crosshead_carries_pump_rod',('pump_piston','pump_rod'):'relation/pump_rod_carries_piston',('crankshaft','hand_crank_arm'):'relation/shaft_to_hand_arm',('hand_crank_arm','handle_pin'):'relation/arm_to_handle_pin',('hand_grip','handle_pin'):'relation/handle_pin_to_grip'}
 C=[]
